import{_ as a,c as i,o as t,a2 as r}from"./chunks/framework.bjzS3PU6.js";const p=JSON.parse('{"title":"G*BOY","description":"","frontmatter":{},"headers":[],"relativePath":"entries/subjects/G-BOY.md","filePath":"entries/subjects/G-BOY.md"}'),o={name:"entries/subjects/G-BOY.md"};function n(s,e,c,l,h,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="g-boy" tabindex="-1">G*BOY <a class="header-anchor" href="#g-boy" aria-label="Permalink to &quot;G*BOY&quot;">​</a></h1><hr><p><strong>DESIGNATION</strong>: Subject G-304<br><strong>FACILITY</strong>: <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a><br><strong>CLASSIFICATION</strong>: Tier-0 Prototype (alleged)<br><strong>STATUS</strong>: Escaped (early 2000s)</p><hr><p><strong>G*BOY</strong> (officially designated <strong>Subject G-304</strong>) is a former research subject who escaped from the <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> in the early 2000s. The escape, which resulted in a facility-wide security failure, drew widespread attention and made G*BOY a symbolic figure for The Bloc, an activist organization investigating alleged corporate research misconduct.</p><p><strong>At a glance</strong></p><ul><li>Former research subject (Designation: G-304) at Saint Juniper Research Campus</li><li>Escaped containment in early 2000s during major facility incident</li><li>Subject of unsuccessful recovery operations led by Nocturne Squadron</li><li>Adopted as symbol by The Bloc activist movement</li><li>Distinctive appearance: red hooded figure</li><li>Current whereabouts unknown</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Subject G-304 was held at the <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> as part of what The Bloc alleges to be unauthorized research programs conducted by the <a href="./../organizations/Miter-Corporation">Miter Corporation</a>. The subject&#39;s escape in the early 2000s resulted in a major facility security breach and triggered recovery operations that, according to facility administrators, proved unsuccessful.</p><p>The subject became widely known following The Bloc&#39;s public awareness campaign, which adopted the red-hooded figure as a symbol of resistance against alleged corporate misconduct. The distinctive appearance and circumstances of the escape contributed to G*BOY becoming a cultural icon within activist communities.</p><h2 id="background-and-containment" tabindex="-1">Background and containment <a class="header-anchor" href="#background-and-containment" aria-label="Permalink to &quot;Background and containment&quot;">​</a></h2><p>Little verified information is publicly available about G-304&#39;s time at the facility. According to claims by The Bloc, the subject was held in a specialized containment area designated Chamber 304 and subjected to experimental procedures. The Bloc alleges that G-304 was part of classified research programs involving what they term &quot;gravitational cognition&quot; experiments, though these claims have not been independently verified.</p><p>The facility has not released official statements regarding the nature of research conducted with G-304 or the circumstances of the subject&#39;s initial intake.</p><h2 id="the-escape" tabindex="-1">The escape <a class="header-anchor" href="#the-escape" aria-label="Permalink to &quot;The escape&quot;">​</a></h2><p>In the early 2000s, G-304 escaped from the Saint Juniper Research Campus in an incident that resulted in significant facility damage and a facility-wide power failure. The Bloc obtained and circulated security footage showing the escape, which depicted extensive structural damage and what appeared to be unusual environmental conditions during the breach.</p><p>Following the escape, facility administrator Dr. Ravel announced that G-304 had been located and that recovery operations led by Agent K and Nocturne Squadron were underway. However, this broadcast was interrupted by <a href="./../people/Z-L1NE">Z*L1NE</a> of The Bloc, who delivered a counter-message to facility personnel. G-304&#39;s whereabouts remain unknown, and no official confirmation of recapture has been issued.</p><h2 id="cultural-impact" tabindex="-1">Cultural impact <a class="header-anchor" href="#cultural-impact" aria-label="Permalink to &quot;Cultural impact&quot;">​</a></h2><p>Following the escape, The Bloc launched a public awareness campaign that adopted G<em>BOY&#39;s distinctive red-hooded appearance as a symbol of resistance. The imagery spread through activist communities in Saint Juniper and beyond, appearing in street art, clothing, and protest materials. The campaign positioned G</em>BOY as a symbol of liberation from alleged corporate experimentation.</p><p>The visual iconography proved effective at raising awareness of The Bloc&#39;s allegations regarding Miter Corporation research practices. G*BOY became the organization&#39;s most recognizable symbol and a rallying point for supporters of their investigative efforts.</p><h2 id="historical-claims" tabindex="-1">Historical claims <a class="header-anchor" href="#historical-claims" aria-label="Permalink to &quot;Historical claims&quot;">​</a></h2><p>Magdalena, operator of the St. Juniper Paranormal Museum and early supporter of The Bloc, has claimed that figures resembling G<em>BOY appear in historical artifacts and ancient texts in her collection. She reports possessing a statue that allegedly predates modern records of G-304&#39;s existence. These claims remain unverified by independent scholars, though they have contributed to G</em>BOY&#39;s mythological status within activist and paranormal research communities.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> — Research facility</li><li><a href="./../people/Z-L1NE">Z*L1NE</a> — Bloc co-founder, broadcast hijacker</li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a> — Alleged facility operator</li><li><a href="./../organizations/Aurelian-Systems">Aurelian Systems</a> — Research partner analyzing G-304 modulation trials</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Regional news coverage of Saint Juniper Research Campus security breach (early 2000s)</li><li>Security footage released by The Bloc showing facility escape</li><li>Dr. Ravel public broadcast regarding recovery operations</li><li>The Bloc public awareness campaign materials</li><li>&quot;G*BOY: Symbol of Resistance or Dangerous Fugitive?&quot; investigative reporting</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',27)])])}const m=a(o,[["render",n]]);export{p as __pageData,m as default};
